// Si llegamos aqui, la cabecera X-Telegram-Bot-Api-Secret-Token ya era
// valida: la comprobo n8n en el nodo Webhook (§4.2).
//
// Reduce el update a lo minimo que el flujo necesita. A diferencia del flujo
// del paciente, aqui hay que distinguir DOCUMENTO de FOTO: Telegram recomprime
// las fotos y destruye el DICOM (§9), asi que una foto no es "otro", es un
// error con su propio codigo y su propio mensaje.
const e = $input.first().json;
const b = e.body || {};
const cb = b.callback_query;
const msg = b.message || b.edited_message;

let chat_id = null, tipo = 'otro', texto = null, dato = null;
let file_id = '', file_size = 0, file_name = '';

if (cb) {
  chat_id = (cb.message && cb.message.chat && cb.message.chat.id) ||
            (cb.from && cb.from.id) || null;
  tipo = 'boton';
  dato = typeof cb.data === 'string' ? cb.data : '';
} else if (msg) {
  chat_id = (msg.chat && msg.chat.id) || null;
  if (msg.document) {
    // Un DICOM enviado como archivo. `document` es lo unico que conserva los
    // bytes tal cual.
    tipo = 'documento';
    file_id = String(msg.document.file_id || '');
    file_size = Number(msg.document.file_size || 0);
    file_name = String(msg.document.file_name || '');
  } else if (Array.isArray(msg.photo) && msg.photo.length) {
    // Telegram ya la recomprimio a JPEG antes de que llegue aqui: no hay
    // DICOM que recuperar, y la cabecera con la edad se perdio con el.
    tipo = 'foto';
  } else if (typeof msg.text === 'string' && msg.text.length > 0) {
    tipo = 'texto';
    texto = msg.text;
  }
  // Sticker, audio, video: se quedan en 'otro' y se repite la pregunta.
}

// Un update sin chat no nos toca. Devolver [] termina la rama sin hacer nada.
if (chat_id === null || chat_id === undefined) { return []; }

// `t0` es el reloj de la latencia de extremo a extremo del §16. Se toma aqui,
// en el primer nodo que corre, y no en el que llama al copiloto: lo que se
// quiere medir es lo que el profesional espera, no lo que tarda el modelo.
return [{ json: { chat_id, tipo, texto, dato, file_id, file_size, file_name,
                  t0: Date.now() } }];

// LA TABLA DE LA CONVERSACION DEL PROFESIONAL. Fuente UNICA de: el paso, la
// clave con la que se guarda cada signo, el rango que se acepta, el texto de la
// pregunta y QUE TECLADO la acompana.
//
// Que el teclado salga de aqui y no de cada nodo de Telegram es el patron 2 de
// la tarea 5: si el `callback_data` del boton y la clave que espera el que
// guarda pudieran divergir, un «Si» de crepitantes acabaria en
// `murmullo_disminuido` sin un solo error. El mensaje saldria perfecto.
//
// Los rangos son los del §4.4 del spec. Fuera de rango NO avanza de paso.
//
// Correspondencia con la prosa del §7/§9 del spec, que numera los pasos de otra
// manera (ahi el 5 es "pide la radiografia"):
//   paso 1 -> §7.1-2  pide el codigo del paciente      (§9 "se queda en el 2")
//   paso 2 -> §7.4    temperatura
//   paso 3 -> §7.4    frecuencia cardiaca
//   paso 4 -> §7.4    crepitantes           (botones)
//   paso 5 -> §7.4    murmullo disminuido   (botones)
//   paso 6 -> §7.5    pide la radiografia              (§9 "se queda en el 5")
const PASOS = [
  {paso: 1, clave: 'codigo',              tipo: 'codigo',    teclado: 'no',
   pregunta: 'Envíeme el código de 6 caracteres que le dio el paciente.'},
  {paso: 2, clave: 'temperatura_c',       tipo: 'decimal',   teclado: 'no',
   min: 30.0, max: 45.0,
   pregunta: 'Temperatura en grados centígrados, entre 30,0 y 45,0. Por ejemplo 38,2.'},
  {paso: 3, clave: 'frecuencia_cardiaca', tipo: 'entero',    teclado: 'no',
   min: 20, max: 250,
   pregunta: 'Frecuencia cardiaca en latidos por minuto: un entero entre 20 y 250.'},
  {paso: 4, clave: 'crepitantes',         tipo: 'booleano',  teclado: 'crepitantes',
   prefijo: 's4', pregunta: 'Se auscultan crepitantes?'},
  {paso: 5, clave: 'murmullo_disminuido', tipo: 'booleano',  teclado: 'murmullo',
   prefijo: 's5', pregunta: 'Hay murmullo vesicular disminuido?'},
  {paso: 6, clave: 'placa',               tipo: 'documento', teclado: 'no',
   pregunta: 'Envíeme la radiografía COMO ARCHIVO (el clip, opción Archivo), no como foto.\n\n' +
             'Telegram recomprime las fotos: destruye el DICOM y con él la edad de la cabecera, que el modelo necesita.'},
];
const ULTIMO = 6;

// El alfabeto del §5.2: 31 caracteres, sin 0, O, 1, I ni L, porque el codigo se
// dicta en voz alta en una consulta.
const ALFABETO = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';

// Telegram no deja descargar por bot ficheros de mas de 20 MB (§9). Se
// comprueba con el `file_size` que viene EN EL UPDATE, antes de pedirle nada a
// Telegram: llamar a getFile para que falle gastaria una peticion y daria un
// error de nodo en vez del mensaje del §9.
const MAXIMO_TELEGRAM = 20 * 1024 * 1024;

// COMO VIAJA UN VALOR A SQL, Y POR QUE ASI. Igual que en el flujo del paciente:
// el nodo Postgres arma sus parametros con `stringToArray`, que parte por COMAS
// y DESCARTA LOS VACIOS. Un valor vacio no se empuja, la consulta sale con un
// parametro menos y Postgres responde `there is no parameter $N`. Por eso todo
// valor lleva un prefijo de un caracter y nunca puede quedar vacio:
//     'N'          -> NULL
//     'T' + base64 -> ese texto
// Para los signos, el texto que viaja es el LITERAL JSON del valor ya tipado
// ("38.2", "104", "true"), y la consulta lo pasa por `::jsonb`. Asi la
// temperatura entra en el jsonb como numero y los crepitantes como booleano,
// que es lo que el §5.3 especifica y lo que H6 espera.
const NULO = 'N';
const codificar = (v) => 'T' + Buffer.from(String(v), 'utf8').toString('base64');

const u = $('Normalizar update').first().json;
const s = $input.first().json;

const texto = (u.texto || '').trim();
const bajo = texto.toLowerCase();
const esComando = (c) =>
  bajo === c || bajo.startsWith(c + ' ') || bajo.startsWith(c + '@');

const actual = PASOS.find((p) => p.paso === s.paso) || null;

const salida = {
  chat_id: u.chat_id,
  t0: u.t0,
  accion: 'nada',
  clave: '',
  valor_cod: NULO,
  codigo_cod: NULO,
  paso: 0,                  // el paso que se va a preguntar o repetir
  paso_actual: s.paso,      // el que la sesion tiene AHORA, para el UPDATE
  reinicio: 'N',
  pregunta: '',
  teclado: 'no',
  file_id: '',
  // Los tres campos con los que `Desenlace` trabaja, iguales en los tres nodos
  // que lo alimentan.
  error_cod: NULO,
  detalle: '',
  resultado: null,
  // Copiados tal cual para que `Desenlace` pueda redactar el §8 sin volver a la
  // base. `Leer sesion y permiso` solo los trae en el paso 6 (§5.4: cuanto
  // menos dato del paciente pase por nodos de n8n, mejor).
  sintomas: s.sintomas || null,
  signos: s.signos || {},
  // El codigo del caso, para la cabecera del mensaje con el texto del
  // paciente. Sale de la sesion, o sea de `cuestionarios`: alfabeto de 31
  // caracteres del §5.2.
  codigo: s.codigo || '',
};

const preguntar = (paso, aviso) => {
  const p = PASOS.find((x) => x.paso === paso);
  salida.accion = 'preguntar';
  salida.paso = paso;
  salida.teclado = p ? p.teclado : 'no';
  salida.pregunta = (aviso ? aviso + '\n\n' : '') + (p ? p.pregunta : '');
};

const desenlace = (codigo, detalle) => {
  salida.accion = 'desenlace';
  salida.error_cod = codigo;
  salida.detalle = detalle || '';
};

// ---------------------------------------------------------------------------
// LA PUERTA. No es un paso del flujo, es una condicion de entrada (§7): un
// profesional dado de baja a mitad de conversacion deja de pasar en el mensaje
// SIGUIENTE, y su sesion se queda intacta, sin avanzar ni borrarse.
// ---------------------------------------------------------------------------
if (!s.autorizado) {
  desenlace('no_autorizado', '');
  return [{ json: salida }];
}

if (u.tipo === 'texto' && esComando('/reiniciar')) {
  // Destructivo y pedido a proposito (§7): borra codigo y signos.
  salida.accion = 'saludo';
  salida.reinicio = 'S';
  salida.paso = 1;
  salida.pregunta = PASOS[0].pregunta;
} else if (u.tipo === 'texto' && esComando('/start')) {
  if (actual && s.paso > 1) {
    // /start a mitad de conversacion NO borra los signos ya recogidos. El
    // destructivo es /reiniciar. Este es el mismo arreglo que hubo que hacer en
    // el flujo del paciente.
    preguntar(actual.paso, '');
  } else {
    salida.accion = 'saludo';
    salida.paso = 1;
    salida.pregunta = PASOS[0].pregunta;
  }
} else if (!s.existe || !actual) {
  // Sin sesion, cualquier mensaje suyo abre una: es un profesional autorizado,
  // no hay consentimiento que pedir, y dejarlo sin respuesta seria un silencio.
  salida.accion = 'saludo';
  salida.paso = 1;
  salida.pregunta = PASOS[0].pregunta;
} else if (actual.tipo === 'codigo') {
  if (u.tipo !== 'texto') {
    preguntar(1, 'Esperaba el código escrito.');
  } else {
    const cod = texto.toUpperCase();
    const valido = cod.length === 6 &&
      cod.split('').every((c) => ALFABETO.indexOf(c) >= 0);
    if (!valido) {
      // Un texto que no tiene forma de codigo no se busca en la base ni se
      // registra en `consultas`: es una errata, no un codigo inexistente.
      // Registrar cada errata inflaria la tasa de rechazos del §16, que es la
      // senal de salud operativa.
      preguntar(1, 'Un codigo son 6 caracteres. El alfabeto no tiene O, 0, I, 1 ni L.');
    } else {
      salida.accion = 'buscar_codigo';
      salida.codigo_cod = codificar(cod);
      salida.paso = 2;
      // La pregunta del paso 2 se resuelve AQUI, desde la tabla, aunque el
      // mensaje lo redacte `Desenlace` junto a los sintomas: si `Desenlace`
      // tuviera su propia copia del texto, las dos podrian divergir y el
      // profesional veria un rango distinto segun por donde llegase.
      salida.teclado = PASOS[1].teclado;
      salida.pregunta = PASOS[1].pregunta;
    }
  }
} else if (actual.tipo === 'documento') {
  if (u.tipo === 'foto') {
    // §9: se queda en este paso, esperando el archivo.
    desenlace('envio_como_foto', '');
  } else if (u.tipo === 'documento' && u.file_size > MAXIMO_TELEGRAM) {
    desenlace('fichero_no_descargable', '');
  } else if (u.tipo === 'documento') {
    salida.accion = 'clasificar';
    salida.file_id = u.file_id;
    salida.paso = ULTIMO;
  } else {
    preguntar(ULTIMO, 'Esperaba un archivo.');
  }
} else if (actual.tipo === 'booleano') {
  if (u.tipo !== 'boton') {
    preguntar(actual.paso, 'Use los botones, por favor.');
  } else {
    const m = /^(s[0-9]+):(si|no)$/.exec(u.dato || '');
    if (!m) {
      salida.accion = 'nada';        // callback ajeno o forjado
    } else if (m[1] !== actual.prefijo) {
      // Boton de OTRA pregunta: un teclado viejo que sigue en la pantalla. Si
      // se aceptara, el «Si» de crepitantes se guardaria en
      // `murmullo_disminuido`. Este es EL fallo silencioso de la tarea.
      preguntar(actual.paso, '');
    } else {
      salida.accion = 'guardar_signo';
      salida.clave = actual.clave;
      salida.valor_cod = codificar(m[2] === 'si' ? 'true' : 'false');
      salida.paso = actual.paso + 1;
      const sig = PASOS.find((x) => x.paso === actual.paso + 1);
      salida.teclado = sig ? sig.teclado : 'no';
      salida.pregunta = sig ? sig.pregunta : '';
    }
  }
} else {
  // decimal o entero: temperatura y frecuencia cardiaca.
  if (u.tipo !== 'texto') {
    preguntar(actual.paso, 'Esperaba un numero escrito.');
  } else {
    // Un 38,2 y un 38.2 son el mismo valor (§4.4): se normaliza a punto antes
    // de comparar y de guardar.
    const crudo = texto.replace(',', '.');
    const esNumero = actual.tipo === 'entero'
      ? /^[0-9]+$/.test(crudo)
      : /^[0-9]+(\.[0-9]+)?$/.test(crudo);
    const n = Number(crudo);
    if (!esNumero || !Number.isFinite(n)) {
      preguntar(actual.paso, 'Eso no lo he entendido como un numero.');
    } else if (n < actual.min || n > actual.max) {
      const fmt = (x) => String(x).replace('.', ',');
      preguntar(actual.paso,
        'Fuera del rango ' + fmt(actual.min) + ' a ' + fmt(actual.max) + '.');
    } else {
      salida.accion = 'guardar_signo';
      salida.clave = actual.clave;
      // JSON.stringify de un numero da el literal JSON ("38.2", "104"), que la
      // consulta convierte con ::jsonb en un numero de verdad, no en una
      // cadena. Sin esto H6 recibiria "38.2" con comillas.
      salida.valor_cod = codificar(JSON.stringify(n));
      salida.paso = actual.paso + 1;
      const sig = PASOS.find((x) => x.paso === actual.paso + 1);
      salida.teclado = sig ? sig.teclado : 'no';
      salida.pregunta = sig ? sig.pregunta : '';
    }
  }
}

return [{ json: salida }];

// La salida de ERROR de `Descargar fichero`.
//
// Sin esta rama, un fallo de Telegram al bajar el fichero -un 5xx suyo, un
// file_id que ya no resuelve- dejaba al profesional SIN NINGUNA respuesta: el
// workflow moria en ese nodo, y como el §5.4 obliga a
// `saveDataErrorExecution: none`, tampoco quedaba rastro de la ejecucion. En una
// herramienta clinica el silencio es el peor desenlace posible: el §9 existe
// precisamente para que toda situacion acabe en un mensaje y en un estado
// conocido.
//
// El codigo es `descarga_fallida`, que NO esta en el §9 y hace falta que este.
// Antes reusaba `fichero_no_descargable`, y ese mensaje dice «Telegram no me deja
// descargar archivos de mas de 20 MB»: para un DICOM de 131 KB es una frase falsa,
// y una frase falsa manda al clinico a revisar el tamano del fichero en vez de
// avisar de que el servicio esta fallando. El estado despues es el mismo que el
// §9 da a los errores de fichero: se queda en el paso de la radiografia.
const d = $('Decidir').first().json;
return [{ json: {
  chat_id: d.chat_id,
  t0: d.t0,
  sintomas: d.sintomas || null,
  signos: d.signos || {},
  error_cod: 'descarga_fallida',
  detalle: '',
  resultado: null,
} }];

// Del binario que bajo de Telegram al base64 que espera el copiloto (§10.1).
//
// TRES CAMINOS, y el orden importa. El ayudante `getBinaryDataBuffer` es el unico
// que funciona igual con el almacenamiento en memoria y con el de sistema de
// ficheros -y el modo lo decide la instalacion del cliente, no este flujo-, pero
// no esta expuesto igual en todas las versiones de n8n: en unas el accesor es
// `helpers` suelto y en otras `this.helpers`, y en un Code node `this` puede
// venir sin definir, con lo que `this.helpers` lanza. Se prueban los dos, y solo
// si ninguno responde se cae a leer `binary.data.data`, que es correcto con
// almacenamiento en memoria y devuelve vacio con el de disco.
//
// `via` dice por donde se resolvio. No es adorno: es lo unico que permite saber,
// desde fuera, si en la instalacion del cliente esta corriendo el camino bueno o
// el de reserva. Con el se midio en el n8n real (ver tests/profesional.mjs).
let ayudantes = null;
try {
  if (typeof helpers !== 'undefined' && helpers &&
      typeof helpers.getBinaryDataBuffer === 'function') {
    ayudantes = helpers;
  }
} catch (err) { ayudantes = null; }
if (!ayudantes) {
  try {
    if (this && this.helpers &&
        typeof this.helpers.getBinaryDataBuffer === 'function') {
      ayudantes = this.helpers;
    }
  } catch (err) { ayudantes = null; }
}

let b64 = '';
let via = 'nada';
if (ayudantes) {
  try {
    b64 = (await ayudantes.getBinaryDataBuffer(0, 'data')).toString('base64');
    via = 'ayudante';
  } catch (err) { b64 = ''; via = 'nada'; }
}
if (!b64) {
  const bin = $input.first().binary;
  b64 = (bin && bin.data && bin.data.data) || '';
  if (b64) { via = 'binario'; }
}

// Si no hubiera bytes por ningun camino, se manda la cadena vacia y el servidor
// contesta con su propio codigo del §9 -`dicom_invalido`-, que es mas honesto que
// inventar aqui un diagnostico de por que no habia fichero.
const d = $('Decidir').first().json;

// EL CUERPO JSON-RPC SE ARMA AQUI, no en una expresion del nodo HTTP.
//
// Medido contra el n8n real el 25-sep-2026: poner
// `={{ JSON.stringify({jsonrpc:'2.0',...}) }}` en el campo JSON del nodo HTTP
// falla con «invalid syntax» y la peticion no llega a salir. El motor de
// expresiones delimita con `{{` y `}}`, y un objeto literal dentro deja
// secuencias `}}}` que el separador corta en el sitio equivocado. El sintoma
// habria sido que TODAS las radiografias contestaran `copiloto_no_responde`.
//
// Con el cuerpo ya serializado aqui, la expresion del nodo es un solo campo sin
// llaves, y el JSON lo construye JavaScript, que es donde se puede probar.
const cuerpo_jsonrpc = JSON.stringify({
  jsonrpc: '2.0',
  id: 1,
  method: 'tools/call',
  params: {name: 'clasificar_radiografia', arguments: {dicom_base64: b64}},
});

// El base64 NO sale por ningun otro campo: solo dentro del cuerpo que va a la
// peticion. Con `saveDataSuccessExecution` y `saveDataErrorExecution` en `none`
// nada de esto se persiste, y cuantos menos campos lo lleven, menos hay que
// confiar en ese ajuste (§5.4).
return [{ json: {chat_id: d.chat_id, t0: d.t0, via, cuerpo_jsonrpc} }];

// Lee la respuesta del copiloto. Todo lo verificado contra el contenedor real
// esta en el §10 del spec, y se volvio a medir el 25-sep-2026 antes de escribir
// esto:
//
//   exito      HTTP 200, cuerpo SSE: "event: message\r\ndata: {...}\r\n\r\n",
//              con result.structuredContent y result.isError = false.
//   isError    HTTP 200, el MISMO envoltorio SSE, sin structuredContent, y el
//              texto en result.content[0].text con el prefijo del SDK:
//              "Error executing tool clasificar_radiografia: <codigo>: <detalle>"
//   413        HTTP 413 y cuerpo "Request body too large": NO hay SSE ni
//              JSON-RPC. Buscar `data:` aqui reventaria (§10.4).
//
// Este nodo NO decide que se le dice al profesional: solo traduce la respuesta a
// (error_cod, detalle, resultado). El mensaje lo redacta `Desenlace`, que es el
// unico sitio donde viven el §8 y la tabla del §9.
const d = $('Decidir').first().json;
const e = $input.first().json;

// Los CODIGOS que el servidor puede poner al principio de su mensaje. Se buscan
// DENTRO del texto (§10.3): partir por el primer ':' devolveria
// "Error executing tool clasificar_radiografia" para todos por igual, que fue
// exactamente el fallo que el §10.3 existe para impedir.
// El valor dice si ese detalle SE PUEDE RELATAR al profesional, y la decision es
// por PROCEDENCIA, no por contenido. Es la regla del §8 aplicada aqui:
//
//   se relata lo que compuso NUESTRO codigo; no se relata lo que compuso un tercero.
//
// Antes esto lo guardaba una lista negra de palabras (`HUELE_A_PROBABILIDAD`), que
// es justo el patron que el §8 abandono, y se colaban tres cadenas forjadas:
// «TRIAJE ― opacidad probable (puntuación 0.9900 ≥ umbral 0.4258)», su version con
// А y О cirilicas, y «HALLAZGO ― opacidad probable. Remita a urgencias.». Solo caia
// el literal con «CRIBADO» y comas decimales. Y el origen importa: el detalle de
// `dicom_invalido` lo arma `inferencia.py` con el texto de la excepcion de pydicom
// sobre BYTES AJENOS, asi que quien suministra el DICOM influye en el.
//
// La clasificacion sale de leer las dos fuentes, y
// `test_flujo_profesional.py` la ata a ellas: un mensaje que interpole `{exc}` NO
// se puede relatar.
const CODIGOS_DEL_SERVIDOR = {
  // aplicacion.py: f"base64_invalido: {exc}" -> el texto es de binascii.
  base64_invalido: false,
  // inferencia.py: f"El fichero no es un DICOM legible: {exc}" -> de pydicom,
  // sobre los bytes que manda quien sea. Este era el agujero.
  dicom_invalido: false,
  // inferencia.py: literal entero, sin interpolar nada.
  edad_desconocida: true,
  // inferencia.py: literal + `edad`, que es lo que devuelve `edad_en_anios` y es
  // `int(digitos)`: un entero y nada mas.
  fuera_de_alcance: true,
  // aplicacion.py: literal + dos enteros.
  payload_excesivo: true,
};

// Lo maximo que se relata del servidor. Telegram corta el mensaje en 4 096
// caracteres y devuelve un error, o sea que el profesional no recibe nada: un
// detalle sin tope convierte una caida del copiloto en un silencio.
const TOPE_DETALLE = 500;

const base = {
  chat_id: d.chat_id,
  t0: d.t0,
  codigo: d.codigo || '',
  sintomas: d.sintomas || null,
  signos: d.signos || {},
  error_cod: 'N',
  // EL CONTRATO DE LOS DOS CAMPOS, que es lo que sostiene la regla del §9:
  //
  //   `detalle`  texto que compuso NUESTRO codigo, y por eso es lo unico que
  //              `Desenlace` le puede relatar al profesional. Va vacio cuando lo
  //              que dijo el servidor lo armo interpolando algo de un tercero.
  //   `crudo`    lo que el servidor dijo, sin tocar. Va SIEMPRE a
  //              `consultas.error` detras del codigo, y no se ensena.
  //
  // Antes eran el mismo campo, y ademas en la rama sin codigo se sustituia por un
  // texto fabricado: para un DICOM truncado no se perdia nada, pero para cualquier
  // otra caida sin codigo se perdia lo unico diagnosticable.
  detalle: '',
  crudo: '',
  resultado: null,
};

const salir = (codigo, detalle, crudo) => [{ json: Object.assign({}, base,
  { error_cod: codigo, detalle: detalle || '', crudo: crudo || detalle || '' }) }];

// `cuerpo` es el nombre que el nodo HTTP Request tiene configurado en
// «Put Output in Field»; los otros son por si alguien cambia ese ajuste y no
// este nodo. Sin esta red, un renombre dejaria el flujo diciendo
// "no se interpretar" para TODAS las radiografias, y el mensaje seria cierto.
// Se lee ANTES de mirar el statusCode porque las tres ramas de error lo
// registran: el cuerpo del 413 es «Request body too large», y el de un 502 del
// proxy es lo unico que dira que el problema no era el copiloto.
const cuerpoCrudo = typeof e.cuerpo === 'string' ? e.cuerpo
  : (typeof e.data === 'string' ? e.data
  : (typeof e.body === 'string' ? e.body : ''));

// El nodo HTTP Request lleva `Never Error`, asi que un 413 o un 500 llegan por
// la salida NORMAL con su statusCode. Por la salida de ERROR solo llegan los
// fallos de transporte -timeout, conexion rechazada, DNS-, y esos items no
// traen statusCode: es asi como se distinguen, sin adivinar por el texto.
if (typeof e.statusCode !== 'number') {
  return salir('copiloto_no_responde', '', 'sin statusCode: ' +
               String((e.error && (e.error.message || e.error)) || 'sin detalle')
               .slice(0, 200));
}
if (e.statusCode === 413) {
  // El limite del TRANSPORTE, que no es el mismo que el del tool (§10.4).
  return salir('payload_excesivo_transporte', '',
               'HTTP 413: ' + cuerpoCrudo.slice(0, 200));
}
if (e.statusCode !== 200 || !cuerpoCrudo) {
  // Cualquier respuesta que no sea 200 con cuerpo se trata como error y NO se
  // intenta parsear (§10.4).
  return salir('copiloto_no_responde', '',
               'HTTP ' + e.statusCode + ': ' + cuerpoCrudo.slice(0, 200));
}

// El JSON viaja en la linea `data:` del evento SSE, no suelto (§10.2).
let sobre = null;
for (const linea of cuerpoCrudo.split(/\r?\n/)) {
  if (linea.startsWith('data:')) {
    try { sobre = JSON.parse(linea.slice(5).trim()); } catch (err) { sobre = null; }
    if (sobre) { break; }
  }
}
const res = sobre && sobre.result;
if (!res) {
  // 200 con algo que no es el SSE que el §10.2 describe. Termina y el texto
  // integro va a `consultas.error`, que es lo que el §9 manda hacer con lo que
  // no se sabe interpretar.
  return salir('error_no_reconocido', cuerpoCrudo.slice(0, 500));
}

if (res.isError) {
  const texto = (res.content && res.content[0] && res.content[0].text) || '';
  for (const codigo of Object.keys(CODIGOS_DEL_SERVIDOR)) {
    const i = texto.indexOf(codigo + ':');
    if (i >= 0) {
      // Acotado EN EL ORIGEN. Sin esto, un detalle de 20 000 caracteres -un
      // volcado de pila, un mensaje de una libreria- daba un primer mensaje de
      // 20 031 contra el limite de 4 096 de Telegram, y el profesional NO RECIBIA
      // NADA. El mismo desenlace que el agujero de `ERRORES[codigo]`, por otra
      // puerta, y alcanzable justo por el caso que el §9 mas teme: una caida del
      // servidor.
      const dice = texto.slice(i + codigo.length + 1).trim().slice(0, TOPE_DETALLE);
      // `detalle` es, POR CONTRATO, texto que compuso nuestro codigo: es lo unico
      // que `Desenlace` puede relatarle al profesional. Cuando el servidor lo armo
      // interpolando la excepcion de un tercero, va vacio y el profesional recibe
      // la redaccion del §9, que es del sistema. El texto crudo NO se pierde: va
      // entero a `consultas.error`, que es donde se diagnostica.
      return salir(codigo, CODIGOS_DEL_SERVIDOR[codigo] ? dice : '', dice);
    }
  }
  // UN isError SIN NINGUN CODIGO NO ES «un codigo desconocido».
  //
  // Medido contra el contenedor el 25-sep-2026 con la misma placa truncada al
  // 1, 5, 10, 25, 50, 75 y 99 %: un DICOM cortado hace saltar en el servidor una
  // excepcion que su `except (InvalidDicomError, ValueError, TypeError)` no
  // atrapa, el SDK la envuelve y DESCARTA el mensaje, y lo que llega es
  // exactamente «Error executing tool clasificar_radiografia», sin `codigo:`.
  //
  // El §9 reserva `error_no_reconocido` para «isError con un codigo
  // desconocido», y lo hace TERMINAR. Aplicarlo aqui cerraba la conversacion de
  // un profesional cuyo unico problema es que el fichero llego a medias -el
  // perfil «fichero corrupto» del §13.1, que la tarea 8 va a generar-. La
  // situacion real es que no se pudo leer esa radiografia: `dicom_invalido`, y
  // se queda esperando el archivo.
  //
  // La distincion es la que hay entre «el servidor me dijo algo que no entiendo»
  // -hay codigo, no lo conozco, y eso es un desajuste de contrato que merece
  // terminar y registrarse- y «el servidor se cayo procesando lo que le mande»,
  // que es una radiografia que no vale. El texto integro se registra igual, con
  // el prefijo del codigo, para que se pueda diagnosticar despues.
  const SIN_CODIGO = /^Error executing tool [A-Za-z0-9_]+\.?\s*$/;
  if (texto === '' || SIN_CODIGO.test(texto)) {
    return salir('dicom_invalido', 'No pude interpretar el contenido del '
                 + 'fichero. Si lo recortó al enviarlo, vuelva a exportarlo '
                 + 'completo.',
                 // El texto del servidor NO se pierde aunque el mensaje que se
                 // ensena sea otro: si algun dia la caida no es del fichero, esto
                 // es lo unico que quedara para averiguarlo.
                 texto === '' ? '(el servidor no dijo nada)' : texto);
  }
  return salir('error_no_reconocido', texto.slice(0, 500));
}

// Exito. `structuredContent` es lo que se guarda tal cual en
// `consultas.resultado` (§5.3). Si no viniera, el mismo JSON esta como texto en
// result.content[0].text (§10.2).
let r = res.structuredContent || null;
if (!r) {
  try { r = JSON.parse((res.content && res.content[0] && res.content[0].text) || ''); }
  catch (err) { r = null; }
}
// Se exigen TODOS los campos que el §8 imprime, y con su tipo. Antes solo se
// comprobaban tres, y un `structuredContent` al que le faltara `umbral` -o que lo
// trajera como cadena- llegaba al redactor y salia «umbral NaN» en un informe
// clinico. Un campo que falta no es una cifra que se pueda mostrar: es una
// respuesta que no se sabe interpretar.
//
// Y `clasificacion` tiene que ser una de las DOS que el servidor puede emitir.
// Cualquier otra cosa no se traduce a una etiqueta, y adivinarla -tratando todo
// lo que no sea `opacidad_probable` como negativo- es lo que hacia que el
// mensaje pudiera decir «sin opacidad probable» con una puntuacion por encima
// del umbral.
const NUMEROS = ['probabilidad_cruda', 'probabilidad_calibrada',
                 'razon_de_verosimilitud', 'umbral'];
const ETIQUETAS = ['opacidad_probable', 'sin_opacidad_probable'];
const completo = r && NUMEROS.every((k) => typeof r[k] === 'number' &&
                                           Number.isFinite(r[k])) &&
                 ETIQUETAS.indexOf(r.clasificacion) >= 0;
if (!completo) {
  return salir('error_no_reconocido', cuerpoCrudo.slice(0, 500));
}

return [{ json: Object.assign({}, base, { resultado: r }) }];

// EL UNICO SITIO DONDE SE REDACTA UN DESENLACE. Aqui viven el §8 (como se
// presenta el resultado) y la tabla del §9 (las ramas de error, con lo que dice
// el bot y en que estado queda la conversacion despues).
//
// Que sean un solo nodo, y no un Switch de once ramas con once nodos de
// Telegram, es deliberado: con once nodos, "ninguna rama de error emite una
// cifra de probabilidad" es una propiedad que hay que comprobar once veces y que
// se rompe la primera vez que alguien anade la doceava. Aqui es una sola linea,
// y `tests/profesional.mjs` la ejecuta contra los valores reales medidos del
// contenedor.
//
// Cuatro nodos lo alimentan, y los cuatro producen la misma forma
// (error_cod, detalle, crudo, resultado, sintomas, signos):
//   - `Decidir`            -> no_autorizado, envio_como_foto, fichero_no_descargable
//   - `Buscar cuestionario`-> el caso encontrado, o codigo_invalido
//   - `Leer respuesta`     -> el resultado del copiloto, o su error
//   - `Descarga fallida`   -> descarga_fallida
//
// =========================================================================
// LA REGLA DEL INFORME, Y POR QUE ESTA ESCRITA AL REVES QUE ANTES
// =========================================================================
//
// **El mensaje del informe se genera SOLO a partir de numeros validados, de
// valores de una enumeracion cerrada, y de literales de este fichero. No lleva
// ni un caracter que haya escrito el paciente.**
//
// La version anterior hacia lo contrario: metia el texto del paciente en el
// informe y le quitaba los caracteres peligrosos. Esa defensa se rodeo por tres
// vias, y la tercera es la que decide:
//
//   1. `U+2015 HORIZONTAL BAR` se ve identica a la raya `U+2014` y pasaba el
//      filtro, como todos los demas homoglifos menos uno. (Medido con node v24 /
//      Unicode 17: los caracteres con la propiedad Dash son 31, no 47.)
//   2. `U+0085 NEXT LINE` es el unico espacio Unicode que el `\s` de JavaScript
//      no cubre, y es clase BK -salto obligatorio- en UAX #14.
//   3. **Sin ningun caracter de control.** 447 caracteres y siete copias del
//      rotulo: al envolverse la burbuja, una fila renderizada empieza por el
//      rotulo en 3 de 7 anchos de pantalla.
//
// La tercera no la arregla ningun filtro de caracteres: «cabe en una linea» es
// cierto en la cadena y falso en la pantalla, porque el salto lo mete el cliente
// de Telegram y no el dato. Alargar la lista negra era perseguir homoglifos para
// siempre.
//
// Invertida, la regla no menciona ningun caracter, y eso es lo que la hace
// sostenible: si manana alguien inventa otro homoglifo, da igual.
//
// El paciente no pierde nada: su texto se manda ENTERO Y SIN FILTRAR en un
// mensaje aparte, detras de UNA linea del sistema en la posicion 0 y de nada mas
// (ver `textoDelPaciente` y el bloque que lo precede, que explica por que una
// linea y no dos). Y el clinico gana algo, que es que deja de haber duda sobre
// quien escribio que.

// --------------------------------------------------------------------------
// §9. Situacion -> codigo, que dice el bot, y si la conversacion TERMINA.
//
// `relata` = se anade el `detalle` SI LO HAY. Y si lo hay lo decide `Leer
// respuesta` por PROCEDENCIA: solo llena `detalle` cuando el texto lo compuso
// nuestro codigo, nunca cuando el servidor lo armo interpolando la excepcion de una
// libreria sobre bytes ajenos (§9: no se reconstruye la frase ni se interpola la
// edad por nuestra cuenta; la edad no viene en ningun campo estructurado cuando hay
// error, solo dentro del texto).
//
// Por eso `dicom_invalido` lleva `relata: true` y sin embargo NO relata nada
// cuando el servidor devolvio codigo: su detalle es de pydicom. Lo que si relata es
// la frase que compone `Leer respuesta` en la rama SIN codigo, que es nuestra.
// --------------------------------------------------------------------------
const ERRORES = {
  // El rechazo de D6. Va a `consultas` igual: el §5.1 guarda tambien los
  // rechazos, y la tasa es la senal del §16.
  //
  // El mensaje es escueto A PROPOSITO: quien llega aqui ha pasado el
  // `secret_token` del §4.2 sin estar en la lista blanca, asi que no se le dan
  // pistas de que hay detras. El §9 lo pide asi.
  //
  // `termina: false` y no `true`, aunque la tabla del §9 diga «termina»: en esta
  // columna `termina` significa BORRAR LA SESION, y a un profesional al que dan
  // de baja a mitad de conversacion se le perderian los signos que ya habia
  // recogido. El §7 dice que deja de pasar en el mensaje siguiente, no que se le
  // tire el estado; si lo reponen, la conversacion sigue donde estaba. Para un
  // intruso da igual: no tiene sesion que borrar.
  no_autorizado: {termina: false, relata: false, texto: 'No autorizado.'},
  envio_como_foto: {termina: false, relata: false, espera: 'archivo', texto:
    'Telegram recomprime las fotos y destruye el DICOM. Envíela como archivo.'},
  dicom_invalido: {termina: false, relata: true, espera: 'archivo', texto:
    'No pude leer esa radiografía.'},
  fuera_de_alcance: {termina: true, relata: true, texto:
    'NO PROCEDE — fuera del alcance del modelo.'},
  edad_desconocida: {termina: true, relata: true, texto:
    'NO PROCEDE — no se puede saber la edad.'},
  base64_invalido: {termina: false, relata: false, espera: 'archivo', texto:
    'No pude leer el archivo.'},
  payload_excesivo: {termina: false, relata: false, espera: 'archivo', texto:
    'El archivo supera los 5 MB.'},
  payload_excesivo_transporte: {termina: false, relata: false, espera: 'archivo',
    texto: 'El archivo supera los 5 MB.'},
  codigo_invalido: {termina: false, relata: false, espera: 'codigo', texto:
    'Ese código no existe o caducó. Pida al paciente que repita el cuestionario.'},
  fichero_no_descargable: {termina: false, relata: false, espera: 'archivo', texto:
    'Telegram no me deja descargar archivos de más de 20 MB.'},
  // NO esta en el §9, y hace falta. Antes esta situacion -Telegram acepta el
  // update pero luego falla al entregar el fichero- reusaba
  // `fichero_no_descargable`, cuyo mensaje acusa al profesional de haber mandado
  // mas de 20 MB. Para un DICOM de 131 KB eso es una frase falsa, y una frase
  // falsa manda al clinico a buscar por donde no es.
  descarga_fallida: {termina: false, relata: false, espera: 'archivo', texto:
    'No pude descargar el archivo de Telegram.\n\n' +
    'Si vuelve a pasar, no es cosa del archivo: avise al responsable.'},
  copiloto_no_responde: {termina: false, relata: false, espera: 'archivo', texto:
    'El servicio de imagen no está disponible. Inténtelo en unos minutos.'},
  error_no_reconocido: {termina: true, relata: false, texto:
    'El servicio devolvió un error que no sé interpretar. Se ha registrado.'},
};

// QUE SIGUE ESPERANDO EL BOT. Una fila con `espera` acaba diciendolo; una sin
// `espera` -las tres que terminan la conversacion, y `no_autorizado`- no dice
// nada, porque no hay nada que esperar.
//
// Esta aqui, en un solo sitio, y no escrito a mano en cada fila, porque escrito a
// mano lo llevaban DOS de las once filas que siguen esperando. Las otras nueve
// dejaban al profesional sin saber si la conversacion seguia viva o tenia que
// empezar de cero: «El archivo supera los 5 MB.» y nada mas, con el bot
// esperando en silencio al otro lado. Un sitio unico tambien hace que no se pueda
// anadir una fila nueva y olvidarse de la coletilla: o declara `espera` o no
// espera.
const SIGO_ESPERANDO = {
  archivo: 'Sigo esperando el archivo.',
  codigo: 'Sigo esperando el código del paciente.',
};

// La coletilla de los dos rechazos por edad. §9: el rechazo por edad es una
// DECISION CLINICA del sistema, no un fallo tecnico, y tiene que llegar como
// tal. Si se filtrara un numero junto al rechazo, alguien lo usaria.
const COLETILLA_EDAD =
  'No hay resultado que dar: el modelo se validó entre 18 y 100 años, y ' +
  'aplicarlo fuera de ahí no significaría nada. Decida clínicamente.';

// AQUI HABIA UNA LISTA NEGRA DE PALABRAS, Y ESTA QUITADA A PROPOSITO.
//
// `HUELE_A_PROBABILIDAD` buscaba «probabilidad», «cribado», «multiplica por» y una
// coma decimal en el mensaje de error, y se colaban tres cadenas forjadas medidas
// contra este nodo: «TRIAJE ― opacidad probable (puntuación 0.9900 ≥ umbral
// 0.4258)», su version con А y О cirilicas, y «HALLAZGO ― opacidad probable.
// Remita a urgencias.». Solo caia el literal con «CRIBADO» y comas decimales. Era
// el mismo patron que el §8 abandono, en la ultima esquina donde quedaba.
//
// Lo que garantiza ahora que ninguna rama de error emita una cifra de probabilidad
// es la PROCEDENCIA, igual que en el informe:
//
//   el mensaje de una rama de error se compone de literales de este fichero y,
//   para los codigos con `relata`, de un `detalle` que POR CONTRATO compuso
//   nuestro codigo (ver el contrato de `detalle` y `crudo` en `Leer respuesta`).
//
// Y de lo que nuestro codigo compone se sabe exactamente que lleva: el detalle de
// `fuera_de_alcance` es un literal mas `edad`, que es un entero; el de
// `edad_desconocida` es un literal entero. Una cifra de probabilidad no puede
// salir de ahi, y no hay nada que buscar en el texto.

// --------------------------------------------------------------------------
// §4.4: como se le ensena al profesional lo que refirio el paciente.
//
// Esta tabla es LA ENUMERACION CERRADA de la regla del informe: al bloque
// REFERIDO POR EL PACIENTE solo llegan cadenas que estan escritas AQUI. Un valor
// que no este se declara como no reconocido y su contenido se va al mensaje del
// paciente, donde no puede hacerse pasar por nada.
//
// El asma conserva sus TRES estados a proposito: convertir `no_se` en un booleano
// seria fabricar el dato, y H6 tiene que decidirlo explicitamente.
// --------------------------------------------------------------------------
const SINTOMAS = {
  fiebre:         {si: 'fiebre sí', no: 'sin fiebre', no_se: 'fiebre: no sabe'},
  tos:            {con_flema: 'tos con flema', seca: 'tos seca', no: 'sin tos'},
  dias_evolucion: {menos_3: 'menos de 3 días', '3_a_7': '3 a 7 días', mas_7: 'más de 7 días'},
  disnea:         {si: 'le falta el aire', no: 'sin falta de aire'},
  dolor_toracico: {si: 'dolor torácico al respirar', no: 'sin dolor torácico'},
  asma:           {si: 'asma sí', no: 'sin asma', no_se: 'asma: no sabe'},
};
const ORDEN_SINTOMAS = ['fiebre', 'tos', 'dias_evolucion', 'disnea',
                        'dolor_toracico', 'asma'];

// CONSULTAR UNA TABLA CON UNA CLAVE QUE VIENE DE FUERA: por propiedad PROPIA y
// comprobando el tipo de lo que sale. Con `tabla[v]` a secas, un valor como
// `constructor`, `toString` o `__proto__` alcanza `Object.prototype`, y con el
// informe imprimiendo «function Object() { [native code] }» en vez del dato.
//
// Las tres comprobaciones NO son redundantes, aunque hoy se solapen, y cada una
// tiene su prueba de mutacion en `tests/profesional.mjs` -se le quita esa linea al
// codigo real y la prueba TIENE que ponerse roja-:
//
//   `typeof v !== 'string'`  una clave que no es cadena (un numero, un array, un
//                            objeto) se convertiria a texto para indexar y podria
//                            acertar con una propiedad heredada.
//   `!propio.call(tabla, v)` lo heredado no cuenta como valor de la enumeracion.
//   `typeof s !== 'string'`  lo que salga de la tabla tiene que ser una frase. Hoy
//                            la enumeracion solo tiene cadenas, asi que esta linea
//                            no se dispara nunca; existe para que el dia que
//                            alguien anida un objeto o un array a la tabla -para
//                            agrupar valores, por ejemplo- el informe no imprima
//                            «[object Object]».
//
// Esta misma disciplina se aplica a `ERRORES[codigo]` mas abajo, y por la misma
// razon: con un `error_cod` de «constructor» la fila salia de Object.prototype,
// `fila.texto` era undefined, y el profesional NO RECIBIA NADA.
// EL CODIGO DEL CASO, validado donde se usa.
//
// Hoy solo puede venir de `generar_codigo()` y del alfabeto de 31 caracteres del
// §5.2, pero eso es una propiedad de OTRO sitio: la columna no tiene CHECK, y el
// dia que alguien inserte un cuestionario a mano o lo importe, esto imprimiria lo
// que le den. Un identificador que se imprime sin validar es el mismo patron que
// ya fallo dos veces en este nodo.
const ALFABETO_CODIGO = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
function codigoODesconocido(v) {
  const s = String(v == null ? '' : v);
  if (s.length !== 6) { return '(código no reconocido)'; }
  for (const c of s) {
    if (ALFABETO_CODIGO.indexOf(c) < 0) { return '(código no reconocido)'; }
  }
  return s;
}

const propio = Object.prototype.hasOwnProperty;
function dePaleta(tabla, v) {
  if (typeof v !== 'string') { return null; }
  if (!propio.call(tabla, v)) { return null; }
  const s = tabla[v];
  return typeof s === 'string' ? s : null;
}

// Lo maximo que se relata de un detalle del servidor. Telegram rechaza un mensaje
// de mas de 4 096 caracteres, y un mensaje rechazado es un profesional que NO
// RECIBE NADA. Todo lo demas de estos mensajes esta acotado por construccion
// -literales, numeros, valores de la enumeracion-: el detalle era el unico cabo
// suelto, y llegaba justo por la rama de una caida del servidor.
const TOPE_DETALLE = 500;

// RECORTAR. Dos lineas, y cada una arregla una cosa DISTINTA: conviene no
// confundirlas, porque una prueba que las mezcle no sujeta ninguna.
//
//  1. `Array.from(...)` recorta por PUNTOS DE CODIGO y no por unidades UTF-16.
//     Eso es lo que hace que «500» signifique 500 caracteres: con `slice(0, 500)`
//     a secas, 500 emoji se quedaban en 250 porque cada uno ocupa dos unidades.
//     Es fidelidad, no seguridad.
//  2. El subrogado alto suelto del final se cae. Eso es lo que garantiza que la
//     cadena este BIEN FORMADA, y hace falta aunque se recorte por puntos de
//     codigo: el bot del paciente guarda con `texto.slice(0, 500)`, o sea por
//     unidades, asi que lo que llega de la base PUEDE venir ya partido. Con
//     `"a".repeat(499) + "😀"` el paciente rompia a voluntad lo que el primer
//     mensaje promete.
function recortar(s, n) {
  let r = Array.from(String(s)).slice(0, n).join('');
  const ultimo = r.charCodeAt(r.length - 1);
  if (ultimo >= 0xD800 && ultimo <= 0xDBFF) { r = r.slice(0, -1); }
  return r;
}

// Numeros en castellano: coma decimal, y el numero de decimales que el §8 fija.
const dec = (x, n) => Number(x).toFixed(n).replace('.', ',');

// Una probabilidad con dos decimales, PERO sin llegar nunca a 0,00 ni a 1,00.
//
// El §8 dice «probabilidades con dos decimales» a secas, y eso aqui se rompe:
// el calibrador desplegado acota la probabilidad a los extremos SOSTENIDOS de
// su curva -0,0046 y 0,9565-, precisamente para que ninguna radiografia
// justifique mas certeza que la que las 3 810 placas de validacion sostienen.
// Con dos decimales a secas, 344 de las 3 811 placas de prueba (9,03 %, medido
// el 25-sep-2026) se presentarian como «probabilidad calibrada 0,00»: certeza
// de ausencia, que es exactamente lo que esa cota existe para no fabricar.
// (El recuento se hace calibrando la cruda SIN redondear, que es lo que
// `inferencia.py` calibra; con la cruda de 4 decimales que viaja en la respuesta
// saldrian 345, y esa es la cifra equivocada.)
const prob = (x) => {
  const v = Number(x);
  if (v > 0 && v < 0.005) { return '< 0,01'; }
  if (v < 1 && v > 0.995) { return '> 0,99'; }
  return dec(v, 2);
};

// Los valores del cuestionario que la enumeracion del §4.4 no contempla. Se
// devuelven aparte para que el informe pueda decir que hay uno sin imprimirlo, y
// para que su contenido viaje al mensaje del paciente, que es donde puede ir sin
// hacerse pasar por nada.
function redactarSintomas(s) {
  if (!s) { return 'REFERIDO POR EL PACIENTE — (el cuestionario ya no está)'; }
  const trozos = ORDEN_SINTOMAS.map(function (clave) {
    const frase = dePaleta(SINTOMAS[clave], s[clave]);
    // Cuando el valor no esta en la enumeracion se dice ESO, y no el valor: el
    // informe no imprime nada que no salga de esta tabla.
    //
    // El valor crudo NO se ensena en ningun mensaje. Antes iba al segundo, con un
    // rotulo que lo explicaba; ese rotulo era una afirmacion del sistema dentro
    // de una burbuja que el paciente controla, o sea justo lo que esta ronda ha
    // quitado. Queda guardado en `cuestionarios.respuestas` y en
    // `consultas.sintomas`, que es donde H7 lo necesita, y el informe dice QUE
    // pregunta no se puede usar, que es la parte accionable: el clinico se lo
    // pregunta al paciente, que lo tiene delante. Hoy la situacion es
    // inalcanzable, porque el bot del paciente solo guarda valores de la tabla.
    return frase === null ? clave + ': (valor no reconocido)' : frase;
  });
  return 'REFERIDO POR EL PACIENTE — ' + trozos.join(', ');
}

// Los cuatro signos del §4.4, con sus tipos. `Decidir` valida los rangos y la
// consulta los guarda con `::jsonb` con su tipo, asi que aqui solo se comprueba
// que siguen siendo lo que eran: un signo que llegara como cadena daria «NaN °C»
// en un informe clinico.
function signosValidos(g) {
  return !!g && typeof g.temperatura_c === 'number' &&
         Number.isFinite(g.temperatura_c) &&
         typeof g.frecuencia_cardiaca === 'number' &&
         Number.isFinite(g.frecuencia_cardiaca) &&
         typeof g.crepitantes === 'boolean' &&
         typeof g.murmullo_disminuido === 'boolean';
}

function redactarSignos(g) {
  if (!signosValidos(g)) { return 'EXPLORADO — (sin datos completos)'; }
  return 'EXPLORADO — ' + [
    dec(g.temperatura_c, 1) + ' °C',
    dec(g.frecuencia_cardiaca, 0) + ' lpm',
    'crepitantes ' + (g.crepitantes ? 'sí' : 'no'),
    g.murmullo_disminuido ? 'murmullo disminuido' : 'murmullo normal',
  ].join(', ');
}

// --------------------------------------------------------------------------
// EL SEGUNDO MENSAJE: SOLO EL TEXTO DEL PACIENTE. NI UN CARACTER MIO.
//
// La version anterior le ponia cabecera y cierre para atribuirlo. Se rodeo: con
// 498 de sus 500 caracteres, el paciente escribe el cierre -«Fin de lo que
// escribió el paciente.»- y detras un informe positivo completo. El cierre de
// verdad queda debajo, y sobre una placa de 0,0047 vuelven a haber dos CRIBADO.
// La forma aguda es peor: en el paso 1→2, con 361 caracteres, el unico bloque con
// forma de cribado de toda la conversacion es el suyo, ANTES de que se haya
// mandado ninguna placa.
//
// El fondo del problema: **cualquier delimitador que escriba el sistema, el
// paciente tambien puede escribirlo.** Lo unico que NO puede fabricar es el limite
// del mensaje: no puede crear una burbuja.
//
// Pero de ahi se saco una conclusion de mas. Lo que se rodeo fue el CIERRE, y se
// tiraron los dos cuando solo uno habia fallado: si el paciente no puede fabricar
// el limite del mensaje, **tampoco puede ponerse delante del primer byte**. La
// posicion 0 es tan suya del sistema como el limite.
//
// Y sin cabecera hay superficies donde la burbuja se ve SOLA -notificacion push,
// vista previa en la lista de chats, reenvio, cita, fijado, busqueda- y ahi su
// atribucion era CERO, con la interfaz rotulandola «[retirado]». El camino
// realista al dano es que el clinico reenvie esa burbuja a un colega.
//
// Estructura final:
//   - UNA linea literal en la POSICION 0, y nada mas. Sin cierre, que es lo que
//     se demostro falsificable.
//   - El aviso del primer mensaje, que sigue siendo el canal que el paciente no
//     puede tocar, y que dice que todo lo que venga detras de esa linea es suyo.
//
// La invariante sigue siendo por igualdad: el mensaje es EXACTAMENTE la cabecera
// mas el texto recortado. Nada entre medias, nada detras.
//
// Sin `parse_mode`, como todo el flujo: un `*` o un `_` suelto no puede romper el
// envio ni inyectar formato (§4.4).
// --------------------------------------------------------------------------
const LIMITE_TEXTO_LIBRE = 500;     // §4.4

// LA CABECERA. Ocupa la posicion 0 y ocupa una sola linea. Va con lo importante
// delante -«TEXTO DEL PACIENTE»- porque en una notificacion push o en la lista de
// chats el sistema corta por donde quiere, y lo que tiene que sobrevivir al corte
// es de quien son esas palabras.
// Declara su ALCANCE, no solo se presenta. Un rotulo que solo nombra lo que viene
// deja un residuo: con 267 caracteres el paciente escribe «Fin de lo que escribió
// el paciente.» y un informe falso detras. En el chat es inofensivo -la burbuja 1 ya
// aviso- pero en un REENVIO visto en frio, no. Diciendo «todo este mensaje» la
// cabecera cubre lo que venga detras sin anadir ningun mecanismo. La alternativa
// -marcar linea por linea- obligaria a volver a definir «que es una linea», y con
// U+2028, U+0085, el retorno de carro y las tabulaciones verticales llegando
// crudos, eso es la ronda 2 otra vez.
const CABECERA_PACIENTE = 'TODO ESTE MENSAJE ES TEXTO DEL PACIENTE, no el informe:\n';

// El aviso, que va en el PRIMER mensaje. Este es el canal que el paciente no puede
// tocar, y por eso es el que explica la cabecera y no al contrario.
const AVISA_DEL_SEGUNDO =
  'El paciente escribió un comentario. Llega en el mensaje siguiente, que empieza ' +
  'por «TODO ESTE MENSAJE ES TEXTO DEL PACIENTE»: nada de lo que hay ahí es mío.';

function textoDelPaciente(s) {
  const libre = s && s.texto_libre;
  if (typeof libre !== 'string') { return ''; }
  // SE DECIDE CON LO QUE SE MANDA, no con el original. Antes la guarda miraba
  // `libre.trim()` y se mandaba `libre.slice(0, 500)`: con 600 espacios y una `x`
  // detras, el informe prometia un comentario y la burbuja eran 500 espacios.
  const recortado = recortar(libre, LIMITE_TEXTO_LIBRE);
  if (recortado.trim() === '') { return ''; }
  return CABECERA_PACIENTE + recortado;
}

// --------------------------------------------------------------------------
// §8. TRES BLOQUES ROTULADOS, y nunca la etiqueta y la razon de verosimilitud
// en el mismo renglon.
//
// La etiqueta sale de `probabilidad_cruda >= umbral`; la RV sale de la curva
// isotonica. SON ESCALAS DISTINTAS. En `cruda ∈ [0,4258 ; 0,5786]` la etiqueta
// es positiva y la RV es menor que 1: el cribado marca la placa y la evidencia
// bayesiana BAJA las probabilidades. Medido sobre el conjunto de prueba el
// 25-sep-2026: 379 de 3 811 placas (9,94 %), que son el 23,3 % de todo lo que el
// cribado etiqueta como positivo -una de cada cuatro veces que hay un positivo-,
// y de esas el 80,5 % no tenia opacidad. El aviso no es un caso raro.
//
// Sin este nodo, juntarlas en un renglon le da al clinico dos afirmaciones
// contradictorias sin pista de cual manda.
// --------------------------------------------------------------------------
// El punto de operacion del §8. Solo se afirma si el `umbral` que devuelve el
// servidor es el que se midio: con otro umbral, sens. y esp. son de OTRO punto
// de la ROC y afirmarlas seria inventarlas.
const UMBRAL_MEDIDO = 0.4258;
const SENSIBILIDAD = 0.88;
const ESPECIFICIDAD = 0.70;

const DESCARGO = 'La combinación de imagen y clínica llega en la siguiente ' +
                 'entrega. Esto no es un diagnóstico.';

// EL AVISO DEL NEGATIVO, y lleva ⚠️ a proposito.
//
// Medido sobre las 3 811 placas del conjunto de prueba: de las que el cribado da
// por negativas, 1 de cada 22 tiene neumonia. Eso no es un descarte, y el mensaje
// no puede leerse como si lo fuera.
//
// El ⚠️ no estaba en la frase que se pidio, y se anade porque sin el los dos
// avisos de este nodo quedaban al reves: el del positivo contradictorio -el caso
// MENOS peligroso, donde equivocarse manda a alguien sano a una prueba de mas-
// llevaba ⚠️, y el del negativo -el caso MAS peligroso, donde equivocarse manda
// a casa a alguien con neumonia- iba sin marca ninguna. El aviso mas importante
// era el menos visible. O lo llevan los dos o no lo lleva ninguno.
const AVISO_NEGATIVO =
  '⚠️ Un resultado negativo no descarta neumonía. Decide usted.';

// Las dos etiquetas que `inferencia.py` puede emitir. `Leer respuesta` rechaza
// cualquier otra, asi que aqui no hay tercer caso posible.
const POSITIVA = 'opacidad_probable';

function redactarResultado(r, sintomas, signos, hayComentario) {
  const positivo = r.clasificacion === POSITIVA;
  const rv = r.razon_de_verosimilitud;
  // La RV con uno o dos decimales, como el §8: dos por debajo de 10, uno por
  // encima, que es donde el segundo decimal ya no informa de nada.
  const rvTexto = dec(rv, rv < 10 ? 2 : 1);

  // La puntuacion con CUATRO decimales, no dos.
  //
  // El §8 dice «probabilidades con dos decimales», pero la puntuacion cruda NO
  // es una probabilidad -es justo lo que esta seccion existe para separar- y
  // ensenarla con dos decimales al lado de un umbral de cuatro produce
  // desigualdades visiblemente falsas: medido sobre el conjunto de prueba,
  // 3 de las 3 811 placas son negativas y saldrian como
  // «puntuación 0,43 < umbral 0,4258». Con cuatro decimales, ninguna.
  //
  // Y el comparador se saca de COMPARAR LOS DOS NUMEROS QUE SE ENSENAN, no de la
  // etiqueta. Sacarlo de la etiqueta hace que la frase pueda ser aritmeticamente
  // falsa: con una `clasificacion` que el servidor no deberia mandar, el mensaje
  // decia «sin opacidad probable» y «0,5649 < 0,4258» a la vez. Asi la
  // desigualdad es siempre cierta sobre lo que se ve.
  //
  // ¿Puede entonces contradecir a la etiqueta? Medido sobre las 3 811 placas:
  // NO, ni una. `inferencia.py` decide la etiqueta con la cruda sin redondear y
  // publica la cruda redondeada a 4; con 4 decimales mostrados las dos
  // decisiones coinciden en todas. Con 2 decimales, en cambio, 3 placas
  // negativas leerian «>= umbral».
  const comparador = r.probabilidad_cruda >= r.umbral ? '≥' : '<';
  let punto = 'puntuación ' + dec(r.probabilidad_cruda, 4) + ' ' + comparador +
              ' umbral ' + dec(r.umbral, 4);
  if (Math.abs(r.umbral - UMBRAL_MEDIDO) < 1e-9) {
    punto += '; punto orientado a detectar, sens. ' + dec(SENSIBILIDAD, 2) +
             ' / esp. ' + dec(ESPECIFICIDAD, 2);
  }

  const bloques = [];
  bloques.push('CRIBADO — ' + (positivo ? 'opacidad probable' : 'sin opacidad probable') +
               '\n(' + punto + ')');

  let evidencia = 'EVIDENCIA DE LA IMAGEN — ' + (rv >= 1
    ? 'multiplica por ' + rvTexto + ' las probabilidades a favor de neumonía'
    : 'reduce a ' + rvTexto + '× las probabilidades a favor de neumonía') +
    ' (probabilidad calibrada ' + prob(r.probabilidad_calibrada) + ')';
  if (positivo && rv < 1) {
    // EL AVISO. Criterio 6 de aceptacion.
    evidencia += '\n⚠️ El cribado marca esta placa por estar orientado a ' +
      'detectar, pero la imagen en sí no apoya el diagnóstico. Decide la clínica.';
  }
  // Y el del negativo, sin condicion sobre la RV: una etiqueta negativa sale de
  // cruda < 0,4258 y la RV no cruza 1 hasta 0,5786, asi que un negativo tiene
  // SIEMPRE la RV por debajo de 1. No hay negativo al que la imagen apoye, y por
  // eso no hay aqui un caso contradictorio simetrico del de arriba.
  if (!positivo) {
    evidencia += '\n' + AVISO_NEGATIVO;
  }
  bloques.push(evidencia);

  // Enumeracion cerrada y numeros validados. Ni un caracter del paciente.
  bloques.push(redactarSintomas(sintomas) + '\n' + redactarSignos(signos));
  bloques.push(DESCARGO);
  // Y EL AVISO DEL SEGUNDO MENSAJE CIERRA ESTE, cuando hay comentario. Al final a
  // proposito: es lo ultimo que el clinico lee antes de que le llegue la otra
  // burbuja. Si no hay comentario no se manda segundo mensaje y el informe NO lo
  // menciona, para que la frase no pierda significado por repetirse en vacio.
  if (hayComentario) { bloques.push(AVISA_DEL_SEGUNDO); }
  return bloques.join('\n\n');
}

// --------------------------------------------------------------------------
const u = $('Normalizar update').first().json;
const d = $('Decidir').first().json;
const e = $input.first().json;

const NULO = 'N';
const codificar = (v) => 'T' + Buffer.from(String(v), 'utf8').toString('base64');

const salida = {
  chat_id: u.chat_id,
  texto: '',              // el informe, o el mensaje de la rama de error
  texto_paciente: '',     // el mensaje aparte; vacio = no se manda
  error_cod: NULO,        // lo que va a consultas.error, ya codificado
  resultado_cod: NULO,    // lo que va a consultas.resultado, ya codificado
  termina: 'N',           // 'S' borra la sesion
  registrar: 'S',         // 'N' no escribe fila en consultas
  // El reloj del §16. Nunca vacio: `stringToArray` descarta los vacios.
  ms: Math.max(0, Date.now() - Number(u.t0 || Date.now())),
};

const codigo = e.error_cod && e.error_cod !== NULO ? String(e.error_cod) : '';
// Lo que el servidor dijo, sin tocar. Va SIEMPRE a `consultas.error` detras del
// codigo, y no solo cuando el codigo es `error_no_reconocido`: si el copiloto se
// cae por algo que no es el fichero -memoria, un modelo que no carga-, el texto
// crudo es lo unico diagnosticable que hay, y antes se perdia.
// Se acepta `detalle` como reserva: los nodos que no hablan con el copiloto
// -Decidir, Buscar cuestionario, Descarga fallida- no tienen texto crudo de
// servidor, y asi cualquier alimentador futuro que solo ponga `detalle` sigue
// dejando registrado lo que sabia.
const crudo = String(e.crudo || e.detalle || '').slice(0, 500);

if (codigo) {
  const fila = propio.call(ERRORES, codigo) ? ERRORES[codigo] : null;
  if (!fila) {
    // Un codigo que esta tabla no conoce. No se inventa un mensaje: se usa el
    // del §9 para lo que no se sabe interpretar.
    salida.texto = ERRORES.error_no_reconocido.texto;
    salida.error_cod = codificar('error_no_reconocido: ' + codigo +
                                 (crudo ? ' | ' + crudo : ''));
    salida.termina = 'S';
  } else {
    let texto = fila.texto;
    if (fila.relata && e.detalle) {
      // ACOTADO. `Leer respuesta` ya lo acota en el origen, y aqui otra vez porque
      // este nodo lo alimentan cuatro sitios y basta que uno no lo haga. Sin tope,
      // un detalle de 20 000 caracteres daba un mensaje de 20 031 contra el limite
      // de 4 096 de Telegram y el profesional NO RECIBIA NADA: una caida del
      // copiloto convertida en silencio, que es el desenlace que el §9 existe para
      // que no ocurra.
      texto += '\n\n' + recortar(e.detalle, TOPE_DETALLE);
    }
    if (codigo === 'fuera_de_alcance' || codigo === 'edad_desconocida') {
      texto += '\n\n' + COLETILLA_EDAD;
    }
    // AL FINAL, detras del detalle y de la coletilla: es lo que el profesional
    // tiene que hacer a continuacion, y lo ultimo que se lee es lo que se hace.
    // `propio.call` por lo mismo que en el resto del nodo: sin el, una fila con
    // `espera: 'constructor'` sacaria una funcion del prototipo y la pegaria al
    // mensaje.
    if (fila.espera && propio.call(SIGO_ESPERANDO, fila.espera)) {
      texto += '\n\n' + SIGO_ESPERANDO[fila.espera];
    }
    // `consultas.error` empieza SIEMPRE por el codigo -el §16 agrupa por el, y
    // se saca con split_part(error, ':', 1)- y detras va el texto crudo del
    // servidor cuando lo hay.
    salida.error_cod = codificar(codigo + (crudo ? ': ' + crudo : ''));
    salida.termina = fila.termina ? 'S' : 'N';
    salida.texto = texto;
  }
  // Un mensaje de error NUNCA va acompanado de un `resultado`. Esto si es una
  // linea y no una regla de procedencia, porque no depende de ningun texto: o hay
  // desenlace clinico o hay rechazo, y nunca los dos.
  salida.resultado_cod = NULO;
} else if (e.resultado) {
  const sintomas = e.sintomas || d.sintomas;
  salida.texto_paciente = textoDelPaciente(sintomas);
  salida.texto = redactarResultado(e.resultado, sintomas, e.signos || d.signos,
                                   salida.texto_paciente !== '');
  salida.resultado_cod = codificar(JSON.stringify(e.resultado));
  salida.termina = 'S';
} else {
  // El caso encontrado: se le ensenan los sintomas referidos y se le pide el
  // primer signo. No es un desenlace clinico, asi que NO escribe en
  // `consultas`: la fila nace cuando hay resultado o rechazo.
  salida.texto_paciente = textoDelPaciente(e.sintomas);
  salida.texto = 'Caso ' + codigoODesconocido(e.codigo) + '\n\n' +
                 redactarSintomas(e.sintomas) + '\n\n' + d.pregunta +
                 (salida.texto_paciente !== '' ? '\n\n' + AVISA_DEL_SEGUNDO : '');
  salida.registrar = 'N';
}

return [{ json: salida }];
